BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "10fab705-da9f-6719-ec0d-3297d5afae40", "before": {"stem": "Q6. If 3x+2 − 3x = 216, what is the value of x?", "choices": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5\n\nAbdelrahman Ghoneem | 01116004434 | EST & SAT Math Page 48"}], "correct": "B", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00207", "source": "Full-Subject Revision June 2026, page 48 Q6; rendered source confirms superscripts", "review_note": "Restored the two exponents, removed footer text, checked factorization and substitution.", "release": true, "fields": {"stem": "If \\(3^{x+2}-3^x=216\\), what is the value of \\(x\\)?", "choices": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "topic": "Exponents, Radicals & Logarithms"}, "explanation": "Factor out \\(3^x\\): \\(3^{x+2}-3^x=3^x(9-1)=8\\cdot3^x=216\\). Hence \\(3^x=27=3^3\\), so \\(x=3\\). Check: \\(3^5-3^3=243-27=216\\).", "correct": "B"}, {"id": "3556fa31-7c75-76db-d8d7-9ee22d7c3867", "before": {"stem": "If 3x+2 − 3x = 216, what is the value of x?", "choices": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "correct": "B", "explanation": "Answer key transcribed from the complete printed source key and structurally validated against the listed choices."}, "source_question_id": "full_subject_revision_june_2026-p48-q214", "source": "Full-Subject Revision June 2026, page 48 Q6; rendered source confirms superscripts", "review_note": "Restored the two exponents, removed footer text, checked factorization and substitution.", "release": true, "fields": {"stem": "If \\(3^{x+2}-3^x=216\\), what is the value of \\(x\\)?", "choices": [{"key": "A", "text": "2"}, {"key": "B", "text": "3"}, {"key": "C", "text": "4"}, {"key": "D", "text": "5"}], "topic": "Exponents, Radicals & Logarithms"}, "explanation": "Factor out \\(3^x\\): \\(3^{x+2}-3^x=3^x(9-1)=8\\cdot3^x=216\\). Hence \\(3^x=27=3^3\\), so \\(x=3\\). Check: \\(3^5-3^3=243-27=216\\).", "correct": "B"}, {"id": "11bda1e3-466b-3bb2-9f02-0d974eafc9fe", "before": {"stem": "For the same function, if a = 1 and the coefficient of the x² term equals the\ncoefficient of the x³ term, what is the value of b?", "choices": [{"key": "A", "text": "−1"}, {"key": "B", "text": "1/2"}, {"key": "C", "text": "1"}, {"key": "D", "text": "3/2"}], "correct": "C", "explanation": "Answer key transcribed from the complete printed source key and structurally validated against the listed choices."}, "source_question_id": "full_subject_revision_june_2026-p15-q71", "source": "Full-Subject Revision June 2026, page 15 Q70–71", "review_note": "Restored the function shared with Q70 so the item is self-contained.", "release": true, "fields": {"stem": "Let \\(f(x)=3ax^3+4bx^2+x+x^3\\), where \\(a\\) and \\(b\\) are real constants. If \\(a=1\\) and the coefficient of \\(x^2\\) equals the coefficient of \\(x^3\\), what is \\(b\\)?", "choices": [{"key": "A", "text": "−1"}, {"key": "B", "text": "1/2"}, {"key": "C", "text": "1"}, {"key": "D", "text": "3/2"}]}, "explanation": "Collect like powers: \\(f(x)=(3a+1)x^3+4bx^2+x\\). With \\(a=1\\), the coefficient of \\(x^3\\) is 4. Therefore \\(4b=4\\), giving \\(b=1\\).", "correct": "C"}, {"id": "97df8a5e-6024-2d0d-a942-c3cf570530db", "before": {"stem": "Q71. For the same function, if a = 1 and the coefficient of the x² term equals the\n coefficient of the x³ term, what is the value of b?", "choices": [{"key": "A", "text": "−1"}, {"key": "B", "text": "1/2"}, {"key": "C", "text": "1"}, {"key": "D", "text": "3/2 01116004434"}], "correct": "C", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00070", "source": "Full-Subject Revision June 2026, page 15 Q70–71", "review_note": "Restored the function shared with Q70 so the item is self-contained.", "release": true, "fields": {"stem": "Let \\(f(x)=3ax^3+4bx^2+x+x^3\\), where \\(a\\) and \\(b\\) are real constants. If \\(a=1\\) and the coefficient of \\(x^2\\) equals the coefficient of \\(x^3\\), what is \\(b\\)?", "choices": [{"key": "A", "text": "−1"}, {"key": "B", "text": "1/2"}, {"key": "C", "text": "1"}, {"key": "D", "text": "3/2"}]}, "explanation": "Collect like powers: \\(f(x)=(3a+1)x^3+4bx^2+x\\). With \\(a=1\\), the coefficient of \\(x^3\\) is 4. Therefore \\(4b=4\\), giving \\(b=1\\).", "correct": "C"}, {"id": "97c00f1c-f888-4ff6-b111-478c90998768", "before": {"stem": "For the same plants (mean = 18 cm), 3 new plants are added and the new\nmean becomes 17 cm. Which could be the heights of the new plants?", "choices": [{"key": "A", "text": "10, 13, 14 cm"}, {"key": "B", "text": "10, 13, 17 cm"}, {"key": "C", "text": "10, 14, 15 cm"}, {"key": "D", "text": "10, 15, 16 cm"}], "correct": "D", "explanation": "Answer key transcribed from the complete printed source key and structurally validated against the listed choices."}, "source_question_id": "full_subject_revision_june_2026-p44-q203", "source": "Full-Subject Revision June 2026, page 44 Q49–50", "review_note": "Restored the ten-plant sample size from Q49; checked the new total.", "release": true, "fields": {"stem": "Ten plants have a mean height of 18 cm. Three plants are added, and the mean height of all 13 plants becomes 17 cm. Which could be the heights of the three added plants?"}, "explanation": "The original total height is \\(10\\times18=180\\) cm. The new total is \\(13\\times17=221\\) cm. The three added heights must sum to \\(221-180=41\\) cm. Only \\(10+15+16=41\\), so D is correct.", "correct": "D"}, {"id": "8a2ed657-7340-f2c3-118f-fa2205210590", "before": {"stem": "Using the same table, what is P(boy | local)?", "choices": [{"key": "A", "text": "0.265"}, {"key": "B", "text": "0.316"}, {"key": "C", "text": "0.447"}, {"key": "D", "text": "0.638"}], "correct": "C", "explanation": "Answer key transcribed from the complete printed source key and structurally validated against the listed choices."}, "source_question_id": "full_subject_revision_june_2026-p39-q178", "source": "Full-Subject Revision June 2026, page 39 Q24–25", "review_note": "Restored the full two-way table and checked the conditional denominator.", "release": true, "fields": {"stem": "A school has 101 local boys, 60 expatriate boys, 125 local girls, and 34 expatriate girls. If a student is chosen at random from the local students, what is the probability that the student is a boy, to three decimal places?", "choices": [{"key": "A", "text": "0.265"}, {"key": "B", "text": "0.316"}, {"key": "C", "text": "0.447"}, {"key": "D", "text": "0.638"}]}, "explanation": "Restrict the sample to local students: there are \\(101+125=226\\). Of these, 101 are boys. Thus \\(P(\\text{boy}\\mid\\text{local})=101/226\\approx0.447\\), choice C.", "correct": "C"}, {"id": "b393ec70-742f-a7a3-6e9f-d947e71164e6", "before": {"stem": "Q25. Using the same table, what is P(boy | local)?", "choices": [{"key": "A", "text": "0.265"}, {"key": "B", "text": "0.316"}, {"key": "C", "text": "0.447"}, {"key": "D", "text": "0.638 Ghoneem"}], "correct": "C", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00173", "source": "Full-Subject Revision June 2026, page 39 Q24–25", "review_note": "Restored the full two-way table and checked the conditional denominator.", "release": true, "fields": {"stem": "A school has 101 local boys, 60 expatriate boys, 125 local girls, and 34 expatriate girls. If a student is chosen at random from the local students, what is the probability that the student is a boy, to three decimal places?", "choices": [{"key": "A", "text": "0.265"}, {"key": "B", "text": "0.316"}, {"key": "C", "text": "0.447"}, {"key": "D", "text": "0.638"}]}, "explanation": "Restrict the sample to local students: there are \\(101+125=226\\). Of these, 101 are boys. Thus \\(P(\\text{boy}\\mid\\text{local})=101/226\\approx0.447\\), choice C.", "correct": "C"}, {"id": "09d57c11-17f3-4a6d-bf9c-85127441d4db", "before": {"stem": "Question 21. Solve |7 − 4x| > 3x + 1.", "choices": [{"key": "A", "text": "x < 7/6"}, {"key": "B", "text": "x < 6/8"}, {"key": "C", "text": "x < 6/7 or x > 8"}, {"key": "D", "text": "x > 7"}, {"key": "E", "text": "x > 6/7 or x < 7"}], "correct": "C", "explanation": "For x<=7/4, 7-4x>3x+1 gives x<6/7. For x>=7/4, 4x-7>3x+1 gives x>8. Thus x<6/7 or x>8."}, "source_question_id": "est2_hs_level1_jan_2026-q00021", "source": "ESTII-HS Math L1 January 2026, physical page 8, Q21 (repeated on page 173)", "review_note": "Visually checked all five printed options; restored fraction grouping and removed page footer.", "release": true, "fields": {"stem": "Which is the solution of \\(|7-4x|>3x+1\\)?", "choices": [{"key": "A", "text": "\\(x<\\frac76\\)"}, {"key": "B", "text": "\\(x<\\frac68\\)"}, {"key": "C", "text": "\\(x<\\frac67\\) or \\(x>8\\)"}, {"key": "D", "text": "\\(x>7\\)"}, {"key": "E", "text": "\\(x>\\frac67\\) or \\(x<7\\)"}]}, "explanation": "If \\(x\\le7/4\\), then \\(|7-4x|=7-4x\\), so \\(7-4x>3x+1\\) gives \\(x<6/7\\). If \\(x>7/4\\), then \\(|7-4x|=4x-7\\), so \\(4x-7>3x+1\\) gives \\(x>8\\). The full solution is \\(x<6/7\\) or \\(x>8\\); the endpoints are excluded.", "correct": "C"}, {"id": "5cf35d24-e7fb-5083-17c9-e7dc4697a9de", "before": {"stem": "Question 21. If |7 −4𝑥| > 3𝑥+ 1, which of the following is the solution of the inequality?", "choices": [{"key": "A", "text": "𝑥< 7\n 6"}, {"key": "B", "text": "𝑥< 6\n 8"}, {"key": "C", "text": "𝑥< 6 or 𝑥> 8\n 7"}, {"key": "D", "text": "𝑥> 7"}, {"key": "E", "text": "𝑥> 6 or 𝑥< 7\n 7\n\n 8\nESTII-HS Math L1 January 2026"}], "correct": "C", "explanation": "For x<=7/4, 7-4x>3x+1 gives x<6/7. For x>=7/4, 4x-7>3x+1 gives x>8. Thus x<6/7 or x>8."}, "source_question_id": "est2_hs_level1_jan_2026-q00281", "source": "ESTII-HS Math L1 January 2026, physical page 8, Q21 (repeated on page 173)", "review_note": "Visually checked all five printed options; restored fraction grouping and removed page footer.", "release": true, "fields": {"stem": "Which is the solution of \\(|7-4x|>3x+1\\)?", "choices": [{"key": "A", "text": "\\(x<\\frac76\\)"}, {"key": "B", "text": "\\(x<\\frac68\\)"}, {"key": "C", "text": "\\(x<\\frac67\\) or \\(x>8\\)"}, {"key": "D", "text": "\\(x>7\\)"}, {"key": "E", "text": "\\(x>\\frac67\\) or \\(x<7\\)"}]}, "explanation": "If \\(x\\le7/4\\), then \\(|7-4x|=7-4x\\), so \\(7-4x>3x+1\\) gives \\(x<6/7\\). If \\(x>7/4\\), then \\(|7-4x|=4x-7\\), so \\(4x-7>3x+1\\) gives \\(x>8\\). The full solution is \\(x<6/7\\) or \\(x>8\\); the endpoints are excluded.", "correct": "C"}, {"id": "0f0b042e-07b3-ed26-ff04-51e8fd399a9e", "before": {"stem": "Question 20. A spinner is divided into 12 sections labeled $0, $1, $2, $5, and $10, as shown\n in the figure above. If the spinner is spun twice and all sectors have equal\n probability of landing on the given arrow, what is the probability of obtaining a\n sum of 10?", "choices": [{"key": "A", "text": "1\n 36"}, {"key": "B", "text": "2\n 36"}, {"key": "C", "text": "4\n 36"}, {"key": "D", "text": "5\n 36"}, {"key": "E", "text": "7\n 36"}], "correct": "D", "explanation": "The spinner has four $5 sectors, one $0 sector and two $10 sectors among 12. Ordered pairs summing to $10 are 4*4 from 5+5 and 2*1*2 from 0+10, totaling 20/144=5/36."}, "source_question_id": "est2_hs_level1_jan_2026-q00020", "source": "ESTII-HS Math L1 January 2026, rendered page 8, Q20", "review_note": "Counted the actual sectors: one $0, four $1, one $2, four $5, two $10. Correct key D is independently confirmed despite the handwritten mark on C.", "release": true, "fields": {"stem": "A fair spinner has 12 equal sectors: one labeled $0, four labeled $1, one labeled $2, four labeled $5, and two labeled $10. It is spun twice independently. What is the probability that the two amounts sum to $10?", "choices": [{"key": "A", "text": "1/36"}, {"key": "B", "text": "2/36"}, {"key": "C", "text": "4/36"}, {"key": "D", "text": "5/36"}, {"key": "E", "text": "7/36"}]}, "explanation": "For a sum of $10, the spins must be $5 and $5, $0 then $10, or $10 then $0. The probability is \\((4/12)^2+2(1/12)(2/12)=20/144=5/36\\), choice D.", "correct": "D"}, {"id": "3441a517-54ce-99ae-888e-e47bc9befcaf", "before": {"stem": "Question 20. A spinner is divided into 12 sections labeled $0, $1, $2, $5, and $10, as shown\n in the figure above. If the spinner is spun twice and all sectors have equal\n probability of landing on the given arrow, what is the probability of obtaining a\n sum of 10?", "choices": [{"key": "A", "text": "1\n 36"}, {"key": "B", "text": "2\n 36"}, {"key": "C", "text": "4\n 36"}, {"key": "D", "text": "5\n 36"}, {"key": "E", "text": "7\n 36"}], "correct": "D", "explanation": "The spinner has four $5 sectors, one $0 sector and two $10 sectors among 12. Ordered pairs summing to $10 are 4*4 from 5+5 and 2*1*2 from 0+10, totaling 20/144=5/36."}, "source_question_id": "est2_hs_level1_jan_2026-q00280", "source": "ESTII-HS Math L1 January 2026, rendered page 8, Q20", "review_note": "Counted the actual sectors: one $0, four $1, one $2, four $5, two $10. Correct key D is independently confirmed despite the handwritten mark on C.", "release": true, "fields": {"stem": "A fair spinner has 12 equal sectors: one labeled $0, four labeled $1, one labeled $2, four labeled $5, and two labeled $10. It is spun twice independently. What is the probability that the two amounts sum to $10?", "choices": [{"key": "A", "text": "1/36"}, {"key": "B", "text": "2/36"}, {"key": "C", "text": "4/36"}, {"key": "D", "text": "5/36"}, {"key": "E", "text": "7/36"}]}, "explanation": "For a sum of $10, the spins must be $5 and $5, $0 then $10, or $10 then $0. The probability is \\((4/12)^2+2(1/12)(2/12)=20/144=5/36\\), choice D.", "correct": "D"}, {"id": "f0fdb1f5-7e1f-5a4d-859b-80c47e1c9f48", "before": {"stem": "In the figure, d₁ and d₂ are two parallel lines. Which of the following is always true?", "choices": [{"key": "A", "text": "z = x"}, {"key": "B", "text": "z = x − y"}, {"key": "C", "text": "x = y − z"}, {"key": "D", "text": "x + z + y = 180"}], "correct": "C", "explanation": "The angle y is an exterior angle of the triangle formed with the upper parallel. It equals x + z, so x = y − z."}, "source_question_id": null, "source": "EST I Questions by Topic, GT009; original figure gt-009-1.png visually inspected", "review_note": "Verified angle positions and exterior-angle relationship in the source diagram.", "release": true, "fields": {}, "explanation": "Because the horizontal lines are parallel, the descending transversal makes the same acute angle \\(x\\) with either line. At the crossing, the left-hand angle \\(y\\) is the sum of the two acute inclinations: \\(y=x+z\\). Rearranging gives \\(x=y-z\\), choice C.", "correct": "C"}, {"id": "985b5cf9-e873-d479-7bff-aacb1a4ffbf7", "before": {"stem": "What is the discriminant of the equation above?", "choices": [{"key": "A", "text": "3"}, {"key": "B", "text": "-3"}, {"key": "C", "text": "=i5"}, {"key": "D", "text": "—21"}], "correct": "B", "explanation": "Independently solved and checked against the original scanned page and printed choices."}, "source_question_id": "revision_1_august_2026-p37-q83", "source": "Revision 1, August 2026, rendered page 37 Q37", "review_note": "Restored the missing quadratic from immediately above the prompt.", "release": true, "fields": {"stem": "What is the discriminant of \\(3x^2-3x+1=0\\)?", "choices": [{"key": "A", "text": "3"}, {"key": "B", "text": "−3"}, {"key": "C", "text": "−15"}, {"key": "D", "text": "−21"}]}, "explanation": "For \\(3x^2-3x+1=0\\), \\(a=3,b=-3,c=1\\). The discriminant is \\(b^2-4ac=9-12=-3\\), choice B.", "correct": "B"}, {"id": "fcb60e9c-cf8e-c6af-c2ef-9f1cadc3fa02", "before": {"stem": "The coordinates of the highest point in the graph of the function\nf(x) = —2x? — 4x + Lare:", "choices": [{"key": "A", "text": "(2,—15)"}, {"key": "B", "text": "(1,-—5)"}, {"key": "C", "text": "(—1,3)"}, {"key": "D", "text": "(—2,1)"}], "correct": "C", "explanation": "Independently solved and checked against the original scanned page and printed choices."}, "source_question_id": "revision_1_august_2026-p38-q86", "source": "Revision 1, August 2026, rendered page 38 Q40", "review_note": "Restored exponent 2 and constant 1 from source.", "release": true, "fields": {"stem": "What are the coordinates of the highest point on the graph of \\(f(x)=-2x^2-4x+1\\)?", "choices": [{"key": "A", "text": "(2, −15)"}, {"key": "B", "text": "(1, −5)"}, {"key": "C", "text": "(−1, 3)"}, {"key": "D", "text": "(−2, 1)"}]}, "explanation": "Complete the square: \\(f(x)=-2(x+1)^2+3\\). Since the squared term is nonnegative and its coefficient is negative, the maximum value is 3 at \\(x=-1\\). The highest point is \\((-1,3)\\), choice C.", "correct": "C"}, {"id": "17f1e262-9da4-4a4f-afbd-eba829a420b8", "before": {"stem": "In the figure, segment $AD$ and segment $BE$ intersect at point $C$, and segment $AD$ is perpendicular to line $\\ell$ at point $A$. Which of the following additional pieces of information is (are) sufficient to determine that triangle $ABC$ is congruent to triangle $DEC$? I. Segment $AD$ is perpendicular to line $m$ at point $D$.  II. $AC=13$ and $DC=13$.", "choices": [{"key": "A", "text": "I is sufficient by itself, but II is not."}, {"key": "B", "text": "II is sufficient by itself, but I is not."}, {"key": "C", "text": "I is sufficient by itself, and II is sufficient by itself."}, {"key": "D", "text": "Neither I nor II is sufficient by itself."}], "correct": "D", "explanation": "Statement I only establishes that both triangles are right triangles — shape information, with no side lengths, which gives similarity at best, not congruence. Statement II gives one pair of congruent sides, and with the vertical angles at $C$ that is still only SA, short of SAS, ASA or SSS. Neither statement alone is enough, so the answer is D."}, "source_question_id": null, "source": "Original stored College Board figure CB-7a11ceea; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": false, "fields": {}, "explanation": "Statement I only establishes that both triangles are right triangles — shape information, with no side lengths, which gives similarity at best, not congruence. Statement II gives one pair of congruent sides, and with the vertical angles at $C$ that is still only SA, short of SAS, ASA or SSS. Neither statement alone is enough, so the answer is D.", "correct": "D", "figure_from_id": "3b2e96ac-13ab-4237-a876-40cec92d571e", "duplicate_of": "3b2e96ac-13ab-4237-a876-40cec92d571e"}, {"id": "3b2e96ac-13ab-4237-a876-40cec92d571e", "before": {"stem": "In the figure, segment $AD$ and segment $BE$ intersect at point $C$, and segment $AD$ is perpendicular to line $\\ell$ at point $A$. Which of the following additional pieces of information is (are) sufficient to determine that triangle $ABC$ is congruent to triangle $DEC$? I. Segment $AD$ is perpendicular to line $m$ at point $D$.  II. $AC=13$ and $DC=13$.", "choices": [{"key": "A", "text": "I is sufficient by itself, but II is not."}, {"key": "B", "text": "II is sufficient by itself, but I is not."}, {"key": "C", "text": "I is sufficient by itself, and II is sufficient by itself."}, {"key": "D", "text": "Neither I nor II is sufficient by itself."}], "correct": "D", "explanation": "Statement I only establishes that both triangles are right triangles — shape information, with no side lengths, which gives similarity at best, not congruence. Statement II gives one pair of congruent sides, and with the vertical angles at $C$ that is still only SA, short of SAS, ASA or SSS. Neither statement alone is enough, so the answer is D."}, "source_question_id": null, "source": "Original stored College Board figure CB-7a11ceea; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": true, "fields": {}, "explanation": "Statement I only establishes that both triangles are right triangles — shape information, with no side lengths, which gives similarity at best, not congruence. Statement II gives one pair of congruent sides, and with the vertical angles at $C$ that is still only SA, short of SAS, ASA or SSS. Neither statement alone is enough, so the answer is D.", "correct": "D", "figure_from_id": "3b2e96ac-13ab-4237-a876-40cec92d571e"}, {"id": "43dcdb8d-fe6f-4e3c-b9cb-7ca209692dbb", "before": {"stem": "In the figure, $\\overline{BC}$ is parallel to $\\overline{DE}$, angle $D$ is a right angle, and $x°$ is the angle at $C$ in triangle $ABC$. If $DE=147$ and $AE=245$, what is the value of $\\tan x°$?", "choices": [{"key": "A", "text": "$\\frac{147}{196}$"}, {"key": "B", "text": "$\\frac{147}{245}$"}, {"key": "C", "text": "$\\frac{196}{147}$"}, {"key": "D", "text": "$\\frac{245}{147}$"}], "correct": "C", "explanation": "Triangle $ADE$ is right-angled at $D$ with hypotenuse $AE=245$ and leg $DE=147$, so $AD=\\sqrt{245^2-147^2}=\\sqrt{60{,}025-21{,}609}=\\sqrt{38{,}416}=196$. Because $\\overline{BC}$ is parallel to $\\overline{DE}$, triangle $ABC$ is similar to triangle $ADE$, and the angle marked $x°$ corresponds to angle $AED$. Therefore $\\tan x°=\\frac{AD}{DE}=\\frac{196}{147}$. Choice B is $\\cos x°$, not the tangent."}, "source_question_id": null, "source": "Original stored College Board figure CB-2757549e; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": true, "fields": {}, "explanation": "Triangle $ADE$ is right-angled at $D$ with hypotenuse $AE=245$ and leg $DE=147$, so $AD=\\sqrt{245^2-147^2}=\\sqrt{60{,}025-21{,}609}=\\sqrt{38{,}416}=196$. Because $\\overline{BC}$ is parallel to $\\overline{DE}$, triangle $ABC$ is similar to triangle $ADE$, and the angle marked $x°$ corresponds to angle $AED$. Therefore $\\tan x°=\\frac{AD}{DE}=\\frac{196}{147}$. Choice B is $\\cos x°$, not the tangent.", "correct": "C", "figure_from_id": "43dcdb8d-fe6f-4e3c-b9cb-7ca209692dbb"}, {"id": "a97b42b6-10bd-4493-9a81-8a51fdb885b8", "before": {"stem": "In the figure, $\\overline{BC}$ is parallel to $\\overline{DE}$, angle $D$ is a right angle, and $x°$ is the angle at $C$ in triangle $ABC$. If $DE=147$ and $AE=245$, what is the value of $\\tan x°$?", "choices": [{"key": "A", "text": "$\\frac{147}{196}$"}, {"key": "B", "text": "$\\frac{147}{245}$"}, {"key": "C", "text": "$\\frac{196}{147}$"}, {"key": "D", "text": "$\\frac{245}{147}$"}], "correct": "C", "explanation": "Triangle $ADE$ is right-angled at $D$ with hypotenuse $AE=245$ and leg $DE=147$, so $AD=\\sqrt{245^2-147^2}=\\sqrt{60{,}025-21{,}609}=\\sqrt{38{,}416}=196$. Because $\\overline{BC}$ is parallel to $\\overline{DE}$, triangle $ABC$ is similar to triangle $ADE$, and the angle marked $x°$ corresponds to angle $AED$. Therefore $\\tan x°=\\frac{AD}{DE}=\\frac{196}{147}$. Choice B is $\\cos x°$, not the tangent."}, "source_question_id": null, "source": "Original stored College Board figure CB-2757549e; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": false, "fields": {}, "explanation": "Triangle $ADE$ is right-angled at $D$ with hypotenuse $AE=245$ and leg $DE=147$, so $AD=\\sqrt{245^2-147^2}=\\sqrt{60{,}025-21{,}609}=\\sqrt{38{,}416}=196$. Because $\\overline{BC}$ is parallel to $\\overline{DE}$, triangle $ABC$ is similar to triangle $ADE$, and the angle marked $x°$ corresponds to angle $AED$. Therefore $\\tan x°=\\frac{AD}{DE}=\\frac{196}{147}$. Choice B is $\\cos x°$, not the tangent.", "correct": "C", "figure_from_id": "43dcdb8d-fe6f-4e3c-b9cb-7ca209692dbb", "duplicate_of": "43dcdb8d-fe6f-4e3c-b9cb-7ca209692dbb"}, {"id": "4f974aba-4002-49c2-bad1-37881e360a86", "before": {"stem": "In the figure, line $t$ intersects lines $r$ and $s$, forming an angle of $24°$ with line $r$ and an angle of $x°$ with line $s$. Which additional piece of information is sufficient to prove that lines $r$ and $s$ are parallel?", "choices": [{"key": "A", "text": "$x<24$"}, {"key": "B", "text": "$x=24$"}, {"key": "C", "text": "$x>24$"}, {"key": "D", "text": "$x-24=360$"}], "correct": "B", "explanation": "The $24°$ angle and the $x°$ angle are alternate interior angles for the transversal $t$. Two lines cut by a transversal are parallel if and only if a pair of alternate interior angles is congruent, so $x=24$ is exactly what is needed."}, "source_question_id": null, "source": "Original stored College Board figure CB-d21270da; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": false, "fields": {}, "explanation": "The $24°$ angle and the $x°$ angle are alternate interior angles for the transversal $t$. Two lines cut by a transversal are parallel if and only if a pair of alternate interior angles is congruent, so $x=24$ is exactly what is needed.", "correct": "B", "figure_from_id": "6b187267-15e0-4d5d-a465-d15013db2fc9", "duplicate_of": "6b187267-15e0-4d5d-a465-d15013db2fc9"}, {"id": "6b187267-15e0-4d5d-a465-d15013db2fc9", "before": {"stem": "In the figure, line $t$ intersects lines $r$ and $s$, forming an angle of $24°$ with line $r$ and an angle of $x°$ with line $s$. Which additional piece of information is sufficient to prove that lines $r$ and $s$ are parallel?", "choices": [{"key": "A", "text": "$x<24$"}, {"key": "B", "text": "$x=24$"}, {"key": "C", "text": "$x>24$"}, {"key": "D", "text": "$x-24=360$"}], "correct": "B", "explanation": "The $24°$ angle and the $x°$ angle are alternate interior angles for the transversal $t$. Two lines cut by a transversal are parallel if and only if a pair of alternate interior angles is congruent, so $x=24$ is exactly what is needed."}, "source_question_id": null, "source": "Original stored College Board figure CB-d21270da; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": true, "fields": {}, "explanation": "The $24°$ angle and the $x°$ angle are alternate interior angles for the transversal $t$. Two lines cut by a transversal are parallel if and only if a pair of alternate interior angles is congruent, so $x=24$ is exactly what is needed.", "correct": "B", "figure_from_id": "6b187267-15e0-4d5d-a465-d15013db2fc9"}, {"id": "6f130540-2c25-454c-b90b-fb3bbf873a01", "before": {"stem": "A group of 10 botanists recorded data on germination rates of a certain type of seed for one growing season. The scatterplot shows the relationship between the number of seeds planted, $x$, and the number of seeds that germinated, $y$, for each botanist. A line of best fit is also shown. Which of the following is the best interpretation of the slope of the line of best fit in this context?", "choices": [{"key": "A", "text": "The number of seeds planted is predicted to increase by 60 seeds every 100 days."}, {"key": "B", "text": "The number of seeds planted is predicted to increase by 300 seeds every 100 days."}, {"key": "C", "text": "The number of seeds that germinate is predicted to increase by 60 seeds for every additional 100 seeds that are planted."}, {"key": "D", "text": "The number of seeds that germinate is predicted to increase by 300 seeds for every additional 100 seeds that are planted."}], "correct": "C", "explanation": "Slope is the change in the y-variable per unit change in the x-variable, so the interpretation must relate germinated seeds to seeds planted. Neither axis measures days, which eliminates A and B. Reading the fitted line, $y$ rises about 60 for every 100 increase in $x$, giving choice C."}, "source_question_id": null, "source": "Original stored College Board figure CB-b3547a10; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": false, "fields": {}, "explanation": "Slope is the change in the y-variable per unit change in the x-variable, so the interpretation must relate germinated seeds to seeds planted. Neither axis measures days, which eliminates A and B. Reading the fitted line, $y$ rises about 60 for every 100 increase in $x$, giving choice C.", "correct": "C", "figure_from_id": "a0454173-a83e-467c-aa30-9bd602639a26", "duplicate_of": "a0454173-a83e-467c-aa30-9bd602639a26"}, {"id": "a0454173-a83e-467c-aa30-9bd602639a26", "before": {"stem": "A group of 10 botanists recorded data on germination rates of a certain type of seed for one growing season. The scatterplot shows the relationship between the number of seeds planted, $x$, and the number of seeds that germinated, $y$, for each botanist. A line of best fit is also shown. Which of the following is the best interpretation of the slope of the line of best fit in this context?", "choices": [{"key": "A", "text": "The number of seeds planted is predicted to increase by 60 seeds every 100 days."}, {"key": "B", "text": "The number of seeds planted is predicted to increase by 300 seeds every 100 days."}, {"key": "C", "text": "The number of seeds that germinate is predicted to increase by 60 seeds for every additional 100 seeds that are planted."}, {"key": "D", "text": "The number of seeds that germinate is predicted to increase by 300 seeds for every additional 100 seeds that are planted."}], "correct": "C", "explanation": "Slope is the change in the y-variable per unit change in the x-variable, so the interpretation must relate germinated seeds to seeds planted. Neither axis measures days, which eliminates A and B. Reading the fitted line, $y$ rises about 60 for every 100 increase in $x$, giving choice C."}, "source_question_id": null, "source": "Original stored College Board figure CB-b3547a10; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": true, "fields": {}, "explanation": "Slope is the change in the y-variable per unit change in the x-variable, so the interpretation must relate germinated seeds to seeds planted. Neither axis measures days, which eliminates A and B. Reading the fitted line, $y$ rises about 60 for every 100 increase in $x$, giving choice C.", "correct": "C", "figure_from_id": "a0454173-a83e-467c-aa30-9bd602639a26"}, {"id": "b019a131-d91c-467b-b7cb-4b1c09d99ff2", "before": {"stem": "The graph of a system of a linear and a quadratic equation is shown. Which system of equations is represented by the graph?", "choices": [{"key": "A", "text": "$y=-5x$ and $y=x^2+8$"}, {"key": "B", "text": "$y=-5x$ and $y=x^2-8$"}, {"key": "C", "text": "$y=5x$ and $y=x^2+8$"}, {"key": "D", "text": "$y=5x$ and $y=x^2-8$"}], "correct": "D", "explanation": "The line passes through the origin and rises, so its slope is positive; reading a second point such as $(1,5)$ gives $y=5x$. The parabola has its vertex at $(0,-8)$, so it is $y=x^2-8$. Choices A and B use a negative slope, and A and C place the vertex at $(0,8)$."}, "source_question_id": null, "source": "Original stored College Board figure CB-f123e039; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": true, "fields": {}, "explanation": "The line passes through the origin and rises, so its slope is positive; reading a second point such as $(1,5)$ gives $y=5x$. The parabola has its vertex at $(0,-8)$, so it is $y=x^2-8$. Choices A and B use a negative slope, and A and C place the vertex at $(0,8)$.", "correct": "D", "figure_from_id": "b019a131-d91c-467b-b7cb-4b1c09d99ff2"}, {"id": "f88be379-415d-487b-8ccd-44c7d57f847d", "before": {"stem": "The graph of a system of a linear and a quadratic equation is shown. Which system of equations is represented by the graph?", "choices": [{"key": "A", "text": "$y=-5x$ and $y=x^2+8$"}, {"key": "B", "text": "$y=-5x$ and $y=x^2-8$"}, {"key": "C", "text": "$y=5x$ and $y=x^2+8$"}, {"key": "D", "text": "$y=5x$ and $y=x^2-8$"}], "correct": "D", "explanation": "The line passes through the origin and rises, so its slope is positive; reading a second point such as $(1,5)$ gives $y=5x$. The parabola has its vertex at $(0,-8)$, so it is $y=x^2-8$. Choices A and B use a negative slope, and A and C place the vertex at $(0,8)$."}, "source_question_id": null, "source": "Original stored College Board figure CB-f123e039; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": false, "fields": {}, "explanation": "The line passes through the origin and rises, so its slope is positive; reading a second point such as $(1,5)$ gives $y=5x$. The parabola has its vertex at $(0,-8)$, so it is $y=x^2-8$. Choices A and B use a negative slope, and A and C place the vertex at $(0,8)$.", "correct": "D", "figure_from_id": "b019a131-d91c-467b-b7cb-4b1c09d99ff2", "duplicate_of": "b019a131-d91c-467b-b7cb-4b1c09d99ff2"}, {"id": "00e36c05-a020-484b-8be4-7f037fd29c5a", "before": {"stem": "The graph of a system of a linear equation and a quadratic equation is shown. A solution to the system is $(x,y)$. What is a possible value of $x$?", "choices": [{"key": "A", "text": "4"}, {"key": "B", "text": "5"}, {"key": "C", "text": "7.2"}, {"key": "D", "text": "8"}], "correct": "A", "explanation": "Solutions to the system are the points where the two graphs intersect. The graph shows intersections at approximately $(4,7.2)$ and $(6,7.2)$, so the possible x-values are 4 and 6. Only 4 appears among the choices. Choice B is the vertex x-value, C is a y-value, and D is an x-intercept of the parabola."}, "source_question_id": null, "source": "Original stored College Board figure CB-5f10c095; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": false, "fields": {}, "explanation": "Solutions to the system are the points where the two graphs intersect. The graph shows intersections at approximately $(4,7.2)$ and $(6,7.2)$, so the possible x-values are 4 and 6. Only 4 appears among the choices. Choice B is the vertex x-value, C is a y-value, and D is an x-intercept of the parabola.", "correct": "A", "figure_from_id": "d3468cc1-3ffb-4b85-9680-a5b083802e60", "duplicate_of": "d3468cc1-3ffb-4b85-9680-a5b083802e60"}, {"id": "d3468cc1-3ffb-4b85-9680-a5b083802e60", "before": {"stem": "The graph of a system of a linear equation and a quadratic equation is shown. A solution to the system is $(x,y)$. What is a possible value of $x$?", "choices": [{"key": "A", "text": "4"}, {"key": "B", "text": "5"}, {"key": "C", "text": "7.2"}, {"key": "D", "text": "8"}], "correct": "A", "explanation": "Solutions to the system are the points where the two graphs intersect. The graph shows intersections at approximately $(4,7.2)$ and $(6,7.2)$, so the possible x-values are 4 and 6. Only 4 appears among the choices. Choice B is the vertex x-value, C is a y-value, and D is an x-intercept of the parabola."}, "source_question_id": null, "source": "Original stored College Board figure CB-5f10c095; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": true, "fields": {}, "explanation": "Solutions to the system are the points where the two graphs intersect. The graph shows intersections at approximately $(4,7.2)$ and $(6,7.2)$, so the possible x-values are 4 and 6. Only 4 appears among the choices. Choice B is the vertex x-value, C is a y-value, and D is an x-intercept of the parabola.", "correct": "A", "figure_from_id": "d3468cc1-3ffb-4b85-9680-a5b083802e60"}, {"id": "4eb33535-f18b-4788-9576-9a6face40e07", "before": {"stem": "As part of a study of lake conditions, water temperature was recorded at 7 different depths below the surface. The scatterplot gives the recorded temperature, in degrees Celsius, against depth, in meters. Which of the following is closest to the slope of a line of best fit for the data shown?", "choices": [{"key": "A", "text": "-0.17"}, {"key": "B", "text": "-2.17"}, {"key": "C", "text": "-6.02"}, {"key": "D", "text": "-8.02"}], "correct": "A", "explanation": "Temperature falls as depth increases, so the slope is negative. Taking two points the fitted line passes near, $(15,21.8)$ and $(70,12.7)$, the slope is $\\frac{12.7-21.8}{70-15}=\\frac{-9.1}{55}\\approx-0.165$. Of the choices, $-0.17$ is closest."}, "source_question_id": null, "source": "Original stored College Board figure CB-70a2776f; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": false, "fields": {}, "explanation": "Temperature decreases as depth increases. Using two well-separated points near the trend, (15, 21.8) and (70, 12.7), gives slope (12.7 − 21.8)/(70 − 15) = −9.1/55 ≈ −0.165 °C per meter. Thus −0.17 is the closest choice. A fitted line need not pass exactly through the measured points.", "correct": "A", "figure_from_id": "dd81de74-67b9-4268-9609-d39ad7e80eed", "duplicate_of": "dd81de74-67b9-4268-9609-d39ad7e80eed"}, {"id": "dd81de74-67b9-4268-9609-d39ad7e80eed", "before": {"stem": "As part of a study of lake conditions, water temperature was recorded at 7 different depths below the surface. The scatterplot gives the recorded temperature, in degrees Celsius, against depth, in meters. Which of the following is closest to the slope of a line of best fit for the data shown?", "choices": [{"key": "A", "text": "-0.17"}, {"key": "B", "text": "-2.17"}, {"key": "C", "text": "-6.02"}, {"key": "D", "text": "-8.02"}], "correct": "A", "explanation": "Temperature falls as depth increases, so the slope is negative. Taking two points the fitted line passes near, $(15,21.8)$ and $(70,12.7)$, the slope is $\\frac{12.7-21.8}{70-15}=\\frac{-9.1}{55}\\approx-0.165$. Of the choices, $-0.17$ is closest."}, "source_question_id": null, "source": "Original stored College Board figure CB-70a2776f; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": true, "fields": {}, "explanation": "Temperature decreases as depth increases. Using two well-separated points near the trend, (15, 21.8) and (70, 12.7), gives slope (12.7 − 21.8)/(70 − 15) = −9.1/55 ≈ −0.165 °C per meter. Thus −0.17 is the closest choice. A fitted line need not pass exactly through the measured points.", "correct": "A", "figure_from_id": "dd81de74-67b9-4268-9609-d39ad7e80eed"}, {"id": "c1abbbbd-5d8e-4cab-af2b-ef63a9305b7f", "before": {"stem": "The functions $f$ and $g$ model the number of participants, in thousands, in two programs $x$ years since 2010. The graphs of $y=f(x)$ and $y=g(x)$ are shown. Which of the following could represent functions $f$ and $g$?", "choices": [{"key": "A", "text": "$f(x)=-\\frac{4}{11}x+13$ and $g(x)=\\frac{2}{11}x+7$"}, {"key": "B", "text": "$f(x)=-\\frac{4}{11}x+7$ and $g(x)=\\frac{2}{11}x+13$"}, {"key": "C", "text": "$f(x)=-\\frac{2}{11}x+13$ and $g(x)=\\frac{4}{11}x+7$"}, {"key": "D", "text": "$f(x)=-\\frac{2}{11}x+7$ and $g(x)=\\frac{4}{11}x+13$"}], "correct": "C", "explanation": "One line starts at $(0,13)$ and falls to $(11,11)$, giving slope $\\frac{11-13}{11}=-\\frac{2}{11}$ and the equation $y=-\\frac{2}{11}x+13$. The other starts at $(0,7)$ and rises to $(11,11)$, giving slope $\\frac{11-7}{11}=\\frac{4}{11}$ and the equation $y=\\frac{4}{11}x+7$. Only choice C pairs each intercept with its matching slope."}, "source_question_id": null, "source": "Original stored College Board figure CB-080e75c2; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": false, "fields": {}, "explanation": "One line starts at $(0,13)$ and falls to $(11,11)$, giving slope $\\frac{11-13}{11}=-\\frac{2}{11}$ and the equation $y=-\\frac{2}{11}x+13$. The other starts at $(0,7)$ and rises to $(11,11)$, giving slope $\\frac{11-7}{11}=\\frac{4}{11}$ and the equation $y=\\frac{4}{11}x+7$. Only choice C pairs each intercept with its matching slope.", "correct": "C", "figure_from_id": "dedf87f0-7381-4b6a-ab92-81d827717eb7", "duplicate_of": "dedf87f0-7381-4b6a-ab92-81d827717eb7"}, {"id": "dedf87f0-7381-4b6a-ab92-81d827717eb7", "before": {"stem": "The functions $f$ and $g$ model the number of participants, in thousands, in two programs $x$ years since 2010. The graphs of $y=f(x)$ and $y=g(x)$ are shown. Which of the following could represent functions $f$ and $g$?", "choices": [{"key": "A", "text": "$f(x)=-\\frac{4}{11}x+13$ and $g(x)=\\frac{2}{11}x+7$"}, {"key": "B", "text": "$f(x)=-\\frac{4}{11}x+7$ and $g(x)=\\frac{2}{11}x+13$"}, {"key": "C", "text": "$f(x)=-\\frac{2}{11}x+13$ and $g(x)=\\frac{4}{11}x+7$"}, {"key": "D", "text": "$f(x)=-\\frac{2}{11}x+7$ and $g(x)=\\frac{4}{11}x+13$"}], "correct": "C", "explanation": "One line starts at $(0,13)$ and falls to $(11,11)$, giving slope $\\frac{11-13}{11}=-\\frac{2}{11}$ and the equation $y=-\\frac{2}{11}x+13$. The other starts at $(0,7)$ and rises to $(11,11)$, giving slope $\\frac{11-7}{11}=\\frac{4}{11}$ and the equation $y=\\frac{4}{11}x+7$. Only choice C pairs each intercept with its matching slope."}, "source_question_id": null, "source": "Original stored College Board figure CB-080e75c2; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": true, "fields": {}, "explanation": "One line starts at $(0,13)$ and falls to $(11,11)$, giving slope $\\frac{11-13}{11}=-\\frac{2}{11}$ and the equation $y=-\\frac{2}{11}x+13$. The other starts at $(0,7)$ and rises to $(11,11)$, giving slope $\\frac{11-7}{11}=\\frac{4}{11}$ and the equation $y=\\frac{4}{11}x+7$. Only choice C pairs each intercept with its matching slope.", "correct": "C", "figure_from_id": "dedf87f0-7381-4b6a-ab92-81d827717eb7"}, {"id": "ef282e93-a54f-4da9-8955-3f079623b2e9", "before": {"stem": "A scatterplot shows the relationship between the number of swans, $y$, in a certain population and the number of years since 1970, $x$, where $0\\le x\\le50$. Which of the following equations is the most appropriate exponential model for the data shown in the scatterplot?", "choices": [{"key": "A", "text": "$y=43(1.04)^{-x}$"}, {"key": "B", "text": "$y=43(1.04)^x$"}, {"key": "C", "text": "$y=288(1.04)^{-x}$"}, {"key": "D", "text": "$y=288(1.04)^x$"}], "correct": "B", "explanation": "The data increase over time, so the model must show growth, not decay — that rules out the negative exponents in A and C. The initial value $a$ is the y-value at $x=0$, which the scatterplot places a little above 40. So $a=43$ fits and $a=288$ does not, leaving $y=43(1.04)^x$."}, "source_question_id": null, "source": "Original stored College Board figure CB-dbd89c59; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": false, "fields": {}, "explanation": "The data increase over time, so the model must show growth, not decay — that rules out the negative exponents in A and C. The initial value $a$ is the y-value at $x=0$, which the scatterplot places a little above 40. So $a=43$ fits and $a=288$ does not, leaving $y=43(1.04)^x$.", "correct": "B", "figure_from_id": "f101ea5f-80a3-4a60-bcb5-f56c28f4aa8a", "duplicate_of": "f101ea5f-80a3-4a60-bcb5-f56c28f4aa8a"}, {"id": "f101ea5f-80a3-4a60-bcb5-f56c28f4aa8a", "before": {"stem": "A scatterplot shows the relationship between the number of swans, $y$, in a certain population and the number of years since 1970, $x$, where $0\\le x\\le50$. Which of the following equations is the most appropriate exponential model for the data shown in the scatterplot?", "choices": [{"key": "A", "text": "$y=43(1.04)^{-x}$"}, {"key": "B", "text": "$y=43(1.04)^x$"}, {"key": "C", "text": "$y=288(1.04)^{-x}$"}, {"key": "D", "text": "$y=288(1.04)^x$"}], "correct": "B", "explanation": "The data increase over time, so the model must show growth, not decay — that rules out the negative exponents in A and C. The initial value $a$ is the y-value at $x=0$, which the scatterplot places a little above 40. So $a=43$ fits and $a=288$ does not, leaving $y=43(1.04)^x$."}, "source_question_id": null, "source": "Original stored College Board figure CB-dbd89c59; visually inspected 2026-09-28", "review_note": "Verified diagram labels, relevant coordinates/angle positions, correct option, and the worked reasoning.", "release": true, "fields": {}, "explanation": "The data increase over time, so the model must show growth, not decay — that rules out the negative exponents in A and C. The initial value $a$ is the y-value at $x=0$, which the scatterplot places a little above 40. So $a=43$ fits and $a=288$ does not, leaving $y=43(1.04)^x$.", "correct": "B", "figure_from_id": "f101ea5f-80a3-4a60-bcb5-f56c28f4aa8a"}, {"id": "4bf880f3-dbf0-52f5-43de-7452a7cf5d71", "before": {"stem": "Question 2. If 𝑝−3𝑞 + 𝑞 = 2𝑝+𝑞 − 11, then the value of 𝑝 in terms of 𝑞 is:\n 4 2 2 4", "choices": [{"key": "A", "text": "− 1 11 5𝑞− 5"}, {"key": "B", "text": "− 1 11 5𝑞+ 5"}, {"key": "C", "text": "−𝑞+ 11\n 3"}, {"key": "D", "text": "3 11 5𝑞− 5"}, {"key": "E", "text": "𝑞+ 11\n 3\n\n 𝑥2+4"}], "correct": "C", "explanation": "Multiplying the printed equation by 4 gives p-3q+2q=4p+2q-11. Thus 3p=11-3q and p=-q+11/3."}, "source_question_id": "est2_hs_level1_jan_2026-q00262", "source": "ESTII-HS Math L1 January 2026 Q2; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "If \\(\\frac{p-3q}{4}+\\frac q2=\\frac{2p+q}{2}-\\frac{11}4\\), which expression gives p in terms of q?", "choices": [{"key": "A", "text": "\\(-\\frac1{5q}-\\frac{11}5\\)"}, {"key": "B", "text": "\\(-\\frac1{5q}+\\frac{11}5\\)"}, {"key": "C", "text": "\\(-q+\\frac{11}3\\)"}, {"key": "D", "text": "\\(\\frac3{5q}-\\frac{11}5\\)"}, {"key": "E", "text": "\\(q+\\frac{11}3\\)"}]}, "explanation": "Multiply by 4: p − 3q + 2q = 4p + 2q − 11. Rearranging gives 3p = 11 − 3q, so \\(p=-q+11/3\\).", "correct": "C"}, {"id": "7b2c3532-d0ee-b299-918e-63be6138078f", "before": {"stem": "Question 3. Let 𝑔(𝑥) = −4𝑥2−5𝑥+6. For which values of 𝑥 is 𝑔(𝑥) undefined?", "choices": [{"key": "A", "text": "𝑥= −2 and 𝑥= − 3\n 4"}, {"key": "B", "text": "𝑥= −2 and 𝑥= 3\n 4"}, {"key": "C", "text": "𝑥= 2 and 𝑥= − 3\n 4"}, {"key": "D", "text": "𝑥= 2 and 𝑥= 3\n 4"}, {"key": "E", "text": "𝑥= 2 and 𝑥= 4\n 3"}], "correct": "B", "explanation": "The denominator factors as -4x^2-5x+6=-(4x-3)(x+2). It is zero at x=3/4 and x=-2."}, "source_question_id": "est2_hs_level1_jan_2026-q00263", "source": "ESTII-HS Math L1 January 2026 Q3; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "For which x-values is \\(g(x)=\\frac{x^2+4}{-4x^2-5x+6}\\) undefined?", "choices": [{"key": "A", "text": "\\(x=-2\\) and \\(x=-3/4\\)"}, {"key": "B", "text": "\\(x=-2\\) and \\(x=3/4\\)"}, {"key": "C", "text": "\\(x=2\\) and \\(x=-3/4\\)"}, {"key": "D", "text": "\\(x=2\\) and \\(x=3/4\\)"}, {"key": "E", "text": "\\(x=2\\) and \\(x=4/3\\)"}], "topic": "Rational, Radical, Exponential & Logarithmic Functions"}, "explanation": "The denominator factors as \\(-4x^2-5x+6=-(4x-3)(x+2)\\). It is zero at x = 3/4 and x = −2. The numerator is positive for every real x, so neither point is removable from the original domain.", "correct": "B"}, {"id": "a0633725-f7d2-ead0-4cc8-e38ca24310e0", "before": {"stem": "Question 4. Consider a line 𝑑 of equation 2𝑦= 3𝑥+ 5. Line 𝐿 is perpendicular to 𝑑, and 𝑇 is\n a line parallel to 𝐿. If 𝐴(−5, 3) is a point on 𝑇, then the equation of 𝑇 is:", "choices": [{"key": "A", "text": "2𝑦−3𝑥= 1"}, {"key": "B", "text": "3𝑦−2𝑥= −3"}, {"key": "C", "text": "3𝑦−2𝑥= −1"}, {"key": "D", "text": "3𝑦+ 2𝑥= −1"}, {"key": "E", "text": "3𝑦+ 2𝑥= 3\n\n 3\nESTII-HS Math L1 January 2026"}], "correct": "D", "explanation": "The given line has slope 3/2, so T has slope -2/3. Passing through (-5,3) gives 3y+2x=-1."}, "source_question_id": "est2_hs_level1_jan_2026-q00264", "source": "ESTII-HS Math L1 January 2026 Q4; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Line d has equation 2y = 3x + 5. Line L is perpendicular to d, and line T is parallel to L. If T passes through (−5, 3), which is its equation?", "choices": [{"key": "A", "text": "2y − 3x = 1"}, {"key": "B", "text": "3y − 2x = −3"}, {"key": "C", "text": "3y − 2x = −1"}, {"key": "D", "text": "3y + 2x = −1"}, {"key": "E", "text": "3y + 2x = 3"}]}, "explanation": "Line d has slope 3/2, so L and T have slope −2/3. Using (−5, 3), y − 3 = (−2/3)(x + 5). Multiplying by 3 and rearranging gives 3y + 2x = −1.", "correct": "D"}, {"id": "c30642f4-b2c8-4264-9725-32c3cbd3e2d1", "before": {"stem": "Question 4. Line d has equation 2y = 3x + 5. Line L is perpendicular to d, and T is parallel to L. If A(−5, 3) lies on T, what is the equation of T?", "choices": [{"key": "A", "text": "2y − 3x = 1"}, {"key": "B", "text": "3y − 2x = −3"}, {"key": "C", "text": "3y − 2x = −1"}, {"key": "D", "text": "3y + 2x = −1"}, {"key": "E", "text": "3y + 2x = 3"}], "correct": "D", "explanation": "The given line has slope 3/2, so T has slope -2/3. Passing through (-5,3) gives 3y+2x=-1."}, "source_question_id": "est2_hs_level1_jan_2026-q00004", "source": "ESTII-HS Math L1 January 2026 Q4; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Line d has equation 2y = 3x + 5. Line L is perpendicular to d, and line T is parallel to L. If T passes through (−5, 3), which is its equation?", "choices": [{"key": "A", "text": "2y − 3x = 1"}, {"key": "B", "text": "3y − 2x = −3"}, {"key": "C", "text": "3y − 2x = −1"}, {"key": "D", "text": "3y + 2x = −1"}, {"key": "E", "text": "3y + 2x = 3"}]}, "explanation": "Line d has slope 3/2, so L and T have slope −2/3. Using (−5, 3), y − 3 = (−2/3)(x + 5). Multiplying by 3 and rearranging gives 3y + 2x = −1.", "correct": "D"}, {"id": "b4ccfdf3-7c73-7a09-a5b8-e77f416a53ba", "before": {"stem": "Question 5. In a geometric sequence, the 5th term is 3,200,000 and the 10th term is 1,024. What\n is the first term of this sequence?", "choices": [{"key": "A", "text": "2 × 109"}, {"key": "B", "text": "2 × 1010"}, {"key": "C", "text": "2 × 1011"}, {"key": "D", "text": "2 × 1016"}, {"key": "E", "text": "2 × 1020\n\n 15, 16, 17, 𝑦, 20, 21, 24, 20"}], "correct": "A", "explanation": "The common ratio satisfies r^5=1024/3200000=1/3125=(1/5)^5. The first term is a5/r^4=3200000*625=2*10^9."}, "source_question_id": "est2_hs_level1_jan_2026-q00265", "source": "ESTII-HS Math L1 January 2026 Q5; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "In a geometric sequence, the fifth term is 3,200,000 and the tenth term is 1,024. What is the first term?", "choices": [{"key": "A", "text": "\\(2\\times10^9\\)"}, {"key": "B", "text": "\\(2\\times10^{10}\\)"}, {"key": "C", "text": "\\(2\\times10^{11}\\)"}, {"key": "D", "text": "\\(2\\times10^{16}\\)"}, {"key": "E", "text": "\\(2\\times10^{20}\\)"}]}, "explanation": "For common ratio r, \\(r^5=1024/3200000=1/3125=(1/5)^5\\), so the real ratio is r = 1/5. Thus \\(a_1=a_5/r^4=3200000\\times625=2\\times10^9\\).", "correct": "A"}, {"id": "f33db1e8-904a-4e5a-8702-f1a73a45fb8d", "before": {"stem": "Question 5. In a geometric sequence, the 5th term is 3,200,000 and the 10th term is 1,024. What is the first term?", "choices": [{"key": "A", "text": "2 × 10⁹"}, {"key": "B", "text": "2 × 10¹⁰"}, {"key": "C", "text": "2 × 10¹¹"}, {"key": "D", "text": "2 × 10¹⁶"}, {"key": "E", "text": "2 × 10²⁰"}], "correct": "A", "explanation": "The common ratio satisfies r^5=1024/3200000=1/3125=(1/5)^5. The first term is a5/r^4=3200000*625=2*10^9."}, "source_question_id": "est2_hs_level1_jan_2026-q00005", "source": "ESTII-HS Math L1 January 2026 Q5; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "In a geometric sequence, the fifth term is 3,200,000 and the tenth term is 1,024. What is the first term?", "choices": [{"key": "A", "text": "\\(2\\times10^9\\)"}, {"key": "B", "text": "\\(2\\times10^{10}\\)"}, {"key": "C", "text": "\\(2\\times10^{11}\\)"}, {"key": "D", "text": "\\(2\\times10^{16}\\)"}, {"key": "E", "text": "\\(2\\times10^{20}\\)"}]}, "explanation": "For common ratio r, \\(r^5=1024/3200000=1/3125=(1/5)^5\\), so the real ratio is r = 1/5. Thus \\(a_1=a_5/r^4=3200000\\times625=2\\times10^9\\).", "correct": "A"}, {"id": "913feccc-10f8-4777-e5a5-793fe176bf59", "before": {"stem": "Question 7. Which of the following functions is the inverse of function 𝑝 defined by\n 𝑥−1\n 𝑝(𝑥) = 𝑥+2?", "choices": [{"key": "A", "text": "𝑝−1(𝑥) = 2𝑥\n 1−𝑥"}, {"key": "B", "text": "𝑝−1(𝑥) = 𝑥−1\n 2𝑥−1"}, {"key": "C", "text": "𝑝−1(𝑥) = 2𝑥−1\n 𝑥+1"}, {"key": "D", "text": "𝑝−1(𝑥) = 1−2𝑥\n 1−𝑥"}, {"key": "E", "text": "𝑝−1(𝑥) = 2𝑥+1\n 1−𝑥"}], "correct": "E", "explanation": "Set y=(x-1)/(x+2). Solving yx+2y=x-1 gives x=(2y+1)/(1-y), so p inverse is (2x+1)/(1-x)."}, "source_question_id": "est2_hs_level1_jan_2026-q00267", "source": "ESTII-HS Math L1 January 2026 Q7; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "If \\(p(x)=\\frac{x-1}{x+2}\\), which expression is its inverse function?", "choices": [{"key": "A", "text": "\\(p^{-1}(x)=\\frac{2x}{1-x}\\)"}, {"key": "B", "text": "\\(p^{-1}(x)=\\frac{x-1}{2x-1}\\)"}, {"key": "C", "text": "\\(p^{-1}(x)=\\frac{2x-1}{x+1}\\)"}, {"key": "D", "text": "\\(p^{-1}(x)=\\frac{1-2x}{1-x}\\)"}, {"key": "E", "text": "\\(p^{-1}(x)=\\frac{2x+1}{1-x}\\)"}]}, "explanation": "Write \\(y=(x-1)/(x+2)\\). Then yx + 2y = x − 1, so x(y − 1) = −1 − 2y and \\(x=(2y+1)/(1-y)\\). Interchanging the variables gives \\(p^{-1}(x)=(2x+1)/(1-x)\\), with x ≠ 1.", "correct": "E"}, {"id": "207b8ccc-eaeb-2ddb-d818-e9d661d2d10d", "before": {"stem": "Question 15. Given an equilateral triangle 𝑀𝑁𝑃 such that 𝑀𝑃= 𝑀𝑁= (2𝑥−5) 𝑐𝑚 and\n 𝑁𝑃= (𝑥+ 2) 𝑐𝑚, the area of ∆𝑀𝑁𝑃 is:", "choices": [{"key": "A", "text": "81 √3 𝑐𝑚2\n 2"}, {"key": "B", "text": "81 √3 𝑐𝑚2\n 4"}, {"key": "C", "text": "81 √3 𝑐𝑚2\n 8"}, {"key": "D", "text": "9 √3 𝑐𝑚2\n 2"}, {"key": "E", "text": "9 √3 𝑐𝑚2\n 4\n\n 6\nESTII-HS Math L1 January 2026"}], "correct": "B", "explanation": "Equilateral sides require 2x-5=x+2, so x=7 and side 9. Its area is (sqrt(3)/4)(9^2)=81sqrt(3)/4."}, "source_question_id": "est2_hs_level1_jan_2026-q00275", "source": "ESTII-HS Math L1 January 2026 Q15; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "An equilateral triangle MNP has MP = MN = (2x − 5) cm and NP = (x + 2) cm. What is its area?", "choices": [{"key": "A", "text": "\\(\\frac{81\\sqrt3}{2}\\text{ cm}^2\\)"}, {"key": "B", "text": "\\(\\frac{81\\sqrt3}{4}\\text{ cm}^2\\)"}, {"key": "C", "text": "\\(\\frac{81\\sqrt3}{8}\\text{ cm}^2\\)"}, {"key": "D", "text": "\\(\\frac{9\\sqrt3}{2}\\text{ cm}^2\\)"}, {"key": "E", "text": "\\(\\frac{9\\sqrt3}{4}\\text{ cm}^2\\)"}]}, "explanation": "Equal sides give 2x − 5 = x + 2, so x = 7 and the side length is 9 cm. An equilateral triangle has area \\(s^2\\sqrt3/4\\), hence \\(81\\sqrt3/4\\) square centimeters.", "correct": "B"}, {"id": "8cef0778-f1c1-4adf-8980-efff0903e649", "before": {"stem": "Question 15. An equilateral triangle has two sides of length (2x − 5) cm and a third side of length (x + 2) cm. Find its area.", "choices": [{"key": "A", "text": "81√3/2 cm²"}, {"key": "B", "text": "81√3/4 cm²"}, {"key": "C", "text": "81√3/8 cm²"}, {"key": "D", "text": "9√3/2 cm²"}, {"key": "E", "text": "9√3/4 cm²"}], "correct": "B", "explanation": "Equilateral sides require 2x-5=x+2, so x=7 and side 9. Its area is (sqrt(3)/4)(9^2)=81sqrt(3)/4."}, "source_question_id": "est2_hs_level1_jan_2026-q00015", "source": "ESTII-HS Math L1 January 2026 Q15; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "An equilateral triangle MNP has MP = MN = (2x − 5) cm and NP = (x + 2) cm. What is its area?", "choices": [{"key": "A", "text": "\\(\\frac{81\\sqrt3}{2}\\text{ cm}^2\\)"}, {"key": "B", "text": "\\(\\frac{81\\sqrt3}{4}\\text{ cm}^2\\)"}, {"key": "C", "text": "\\(\\frac{81\\sqrt3}{8}\\text{ cm}^2\\)"}, {"key": "D", "text": "\\(\\frac{9\\sqrt3}{2}\\text{ cm}^2\\)"}, {"key": "E", "text": "\\(\\frac{9\\sqrt3}{4}\\text{ cm}^2\\)"}]}, "explanation": "Equal sides give 2x − 5 = x + 2, so x = 7 and the side length is 9 cm. An equilateral triangle has area \\(s^2\\sqrt3/4\\), hence \\(81\\sqrt3/4\\) square centimeters.", "correct": "B"}, {"id": "4fddd491-c71b-4ecd-a375-c7d11ddf4e56", "before": {"stem": "Question 18. Let f(x) = x³ − 3, g(x) = 4x² + 1, and h(x) = x. Find (g ∘ f ∘ h)(x).", "choices": [{"key": "A", "text": "4x⁶ + 24x³ + 36"}, {"key": "B", "text": "4x⁶ − 24x³ + 37"}, {"key": "C", "text": "4x⁵ + 24x³ − 37"}, {"key": "D", "text": "4x⁵ + 18x³ + 36"}, {"key": "E", "text": "4x⁵ − 18x³ + 1"}], "correct": "B", "explanation": "g(f(h(x)))=4(x^3-3)^2+1=4x^6-24x^3+37."}, "source_question_id": "est2_hs_level1_jan_2026-q00018", "source": "ESTII-HS Math L1 January 2026 Q18; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "If \\(f(x)=x^3-3\\), \\(g(x)=4x^2+1\\), and \\(h(x)=x\\), what is \\((g\\circ f\\circ h)(x)\\)?", "choices": [{"key": "A", "text": "\\(4x^6+24x^3+36\\)"}, {"key": "B", "text": "\\(4x^6-24x^3+37\\)"}, {"key": "C", "text": "\\(4x^5+24x^3-37\\)"}, {"key": "D", "text": "\\(4x^5+18x^3+36\\)"}, {"key": "E", "text": "\\(4x^5-18x^3+1\\)"}]}, "explanation": "First \\(f(h(x))=x^3-3\\). Then \\(g(f(h(x)))=4(x^3-3)^2+1=4(x^6-6x^3+9)+1=4x^6-24x^3+37\\).", "correct": "B"}, {"id": "9094100b-200e-ee40-5c3d-b164b2033f70", "before": {"stem": "Question 18. If 𝑓, 𝑔, and ℎ are three functions defined by 𝑓(𝑥) = 𝑥3 −3, 𝑔(𝑥) = 4𝑥2 + 1, and\n ℎ(𝑥) = 𝑥, then (𝑔∘𝑓∘ℎ)(𝑥) =", "choices": [{"key": "A", "text": "4𝑥6 + 24𝑥3 + 36"}, {"key": "B", "text": "4𝑥6 −24𝑥3 + 37"}, {"key": "C", "text": "4𝑥5 + 24𝑥3 −37"}, {"key": "D", "text": "4𝑥5 + 18𝑥3 + 36"}, {"key": "E", "text": "4𝑥5 −18𝑥3 + 1\n\n 7\nESTII-HS Math L1 January 2026"}], "correct": "B", "explanation": "g(f(h(x)))=4(x^3-3)^2+1=4x^6-24x^3+37."}, "source_question_id": "est2_hs_level1_jan_2026-q00278", "source": "ESTII-HS Math L1 January 2026 Q18; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "If \\(f(x)=x^3-3\\), \\(g(x)=4x^2+1\\), and \\(h(x)=x\\), what is \\((g\\circ f\\circ h)(x)\\)?", "choices": [{"key": "A", "text": "\\(4x^6+24x^3+36\\)"}, {"key": "B", "text": "\\(4x^6-24x^3+37\\)"}, {"key": "C", "text": "\\(4x^5+24x^3-37\\)"}, {"key": "D", "text": "\\(4x^5+18x^3+36\\)"}, {"key": "E", "text": "\\(4x^5-18x^3+1\\)"}]}, "explanation": "First \\(f(h(x))=x^3-3\\). Then \\(g(f(h(x)))=4(x^3-3)^2+1=4(x^6-6x^3+9)+1=4x^6-24x^3+37\\).", "correct": "B"}, {"id": "20cedb1e-7d26-a359-c7c9-b50c387751bc", "before": {"stem": "Question 19. A simplified form of the expression × is:\n 3 4", "choices": [{"key": "A", "text": "5 sin(𝑥) ∙cos(𝑥)\n 3"}, {"key": "B", "text": "cot(𝑥)"}, {"key": "C", "text": "2 tan(𝑥)"}, {"key": "D", "text": "5\n 3"}, {"key": "E", "text": "20\n 3"}], "correct": "D", "explanation": "tan x+cot x=(sin^2 x+cos^2 x)/(sin x cos x)=1/(sin x cos x). Multiplying the printed factors gives 20/(3*4)=5/3."}, "source_question_id": "est2_hs_level1_jan_2026-q00279", "source": "ESTII-HS Math L1 January 2026 Q19; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Simplify \\(\\frac{20\\sin x\\cos x}{3}\\times\\frac{\\tan x+\\cot x}{4}\\), for values of x where the expression is defined.", "choices": [{"key": "A", "text": "\\(\\frac53\\sin x\\cos x\\)"}, {"key": "B", "text": "\\(\\cot x\\)"}, {"key": "C", "text": "\\(2\\tan x\\)"}, {"key": "D", "text": "\\(\\frac53\\)"}, {"key": "E", "text": "\\(\\frac{20}3\\)"}]}, "explanation": "On the domain of the original expression, \\(\\tan x+\\cot x=(\\sin^2x+\\cos^2x)/(\\sin x\\cos x)=1/(\\sin x\\cos x)\\). The product is therefore \\(20/(3\\cdot4)=5/3\\).", "correct": "D"}, {"id": "4b03311e-c655-a42b-07f4-d509b21592f4", "before": {"stem": "Question 19. A simplified form of the expression × is:\n 3 4", "choices": [{"key": "A", "text": "5 sin(𝑥) ∙cos(𝑥)\n 3"}, {"key": "B", "text": "cot(𝑥)"}, {"key": "C", "text": "2 tan(𝑥)"}, {"key": "D", "text": "5\n 3"}, {"key": "E", "text": "20\n 3"}], "correct": "D", "explanation": "tan x+cot x=(sin^2 x+cos^2 x)/(sin x cos x)=1/(sin x cos x). Multiplying the printed factors gives 20/(3*4)=5/3."}, "source_question_id": "est2_hs_level1_jan_2026-q00019", "source": "ESTII-HS Math L1 January 2026 Q19; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": false, "fields": {"stem": "Simplify \\(\\frac{20\\sin x\\cos x}{3}\\times\\frac{\\tan x+\\cot x}{4}\\), for values of x where the expression is defined.", "choices": [{"key": "A", "text": "\\(\\frac53\\sin x\\cos x\\)"}, {"key": "B", "text": "\\(\\cot x\\)"}, {"key": "C", "text": "\\(2\\tan x\\)"}, {"key": "D", "text": "\\(\\frac53\\)"}, {"key": "E", "text": "\\(\\frac{20}3\\)"}]}, "explanation": "On the domain of the original expression, \\(\\tan x+\\cot x=(\\sin^2x+\\cos^2x)/(\\sin x\\cos x)=1/(\\sin x\\cos x)\\). The product is therefore \\(20/(3\\cdot4)=5/3\\).", "correct": "D", "duplicate_of": "20cedb1e-7d26-a359-c7c9-b50c387751bc"}, {"id": "4f1d8e88-f6f9-200e-8112-594ec20c8511", "before": {"stem": "Question 22. 𝐴𝐵𝐶 is a right triangle as shown in the figure above. If 𝐴𝐵= 5𝑥−6 and 𝐵𝐶= 2𝑥,\n which of the following is true if 𝐴𝐵𝐶 is also isosceles? (Figure not drawn to scale)", "choices": [{"key": "A", "text": "𝑥= 6\n 7"}, {"key": "B", "text": "𝑥= 30−6√2\n 23"}, {"key": "C", "text": "𝑥= 6\n 5"}, {"key": "D", "text": "𝑥= 2"}, {"key": "E", "text": "None of the above"}], "correct": "E", "explanation": "A right isosceles triangle has equal legs and hypotenuse 2x. Thus 5x-6=sqrt(2)x, giving x=6/(5-sqrt(2))=(30+6sqrt(2))/23. None of the printed choices matches."}, "source_question_id": "est2_hs_level1_jan_2026-q00282", "source": "ESTII-HS Math L1 January 2026 Q22; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Triangle ABC is right-angled at A, with AB = 5x − 6 and hypotenuse BC = 2x. If the triangle is also isosceles, which statement is true?", "choices": [{"key": "A", "text": "\\(x=6/7\\)"}, {"key": "B", "text": "\\(x=(30-6\\sqrt2)/23\\)"}, {"key": "C", "text": "\\(x=6/5\\)"}, {"key": "D", "text": "x = 2"}, {"key": "E", "text": "None of the above"}]}, "explanation": "In a right isosceles triangle the hypotenuse is √2 times a leg. Thus \\(2x=\\sqrt2(5x-6)\\), or \\(5x-6=\\sqrt2x\\). Solving gives \\(x=6/(5-\\sqrt2)=(30+6\\sqrt2)/23\\). This is positive and produces positive side lengths, but none of A–D equals it.", "correct": "E"}, {"id": "b2178b81-3ecf-63c7-68f3-e45b90c54a7f", "before": {"stem": "Question 22. 𝐴𝐵𝐶 is a right triangle as shown in the figure above. If 𝐴𝐵= 5𝑥−6 and 𝐵𝐶= 2𝑥,\n which of the following is true if 𝐴𝐵𝐶 is also isosceles? (Figure not drawn to scale)", "choices": [{"key": "A", "text": "𝑥= 6\n 7"}, {"key": "B", "text": "𝑥= 30−6√2\n 23"}, {"key": "C", "text": "𝑥= 6\n 5"}, {"key": "D", "text": "𝑥= 2"}, {"key": "E", "text": "None of the above"}], "correct": "E", "explanation": "A right isosceles triangle has equal legs and hypotenuse 2x. Thus 5x-6=sqrt(2)x, giving x=6/(5-sqrt(2))=(30+6sqrt(2))/23. None of the printed choices matches."}, "source_question_id": "est2_hs_level1_jan_2026-q00022", "source": "ESTII-HS Math L1 January 2026 Q22; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Triangle ABC is right-angled at A, with AB = 5x − 6 and hypotenuse BC = 2x. If the triangle is also isosceles, which statement is true?", "choices": [{"key": "A", "text": "\\(x=6/7\\)"}, {"key": "B", "text": "\\(x=(30-6\\sqrt2)/23\\)"}, {"key": "C", "text": "\\(x=6/5\\)"}, {"key": "D", "text": "x = 2"}, {"key": "E", "text": "None of the above"}]}, "explanation": "In a right isosceles triangle the hypotenuse is √2 times a leg. Thus \\(2x=\\sqrt2(5x-6)\\), or \\(5x-6=\\sqrt2x\\). Solving gives \\(x=6/(5-\\sqrt2)=(30+6\\sqrt2)/23\\). This is positive and produces positive side lengths, but none of A–D equals it.", "correct": "E"}, {"id": "76aca08e-6b22-27d6-2ce8-bd56623e5979", "before": {"stem": "Question 23. In the figure above, the area of the shaded part is: (Figure not drawn to scale)", "choices": [{"key": "A", "text": "100𝜋 𝑚2"}, {"key": "B", "text": "250𝜋 𝑚2"}, {"key": "C", "text": "1,000𝜋 𝑚2"}, {"key": "D", "text": "1,250𝜋 𝑚2"}, {"key": "E", "text": "2,500𝜋 𝑚2\n\n 9\nESTII-HS Math L1 January 2026"}], "correct": "E", "explanation": "The 100 m outer-circle chord is tangent to the inner circle at its midpoint. Half the chord is 50 m, so R^2-r^2=50^2. The shaded annulus area is pi(R^2-r^2)=2500pi square meters."}, "source_question_id": "est2_hs_level1_jan_2026-q00283", "source": "ESTII-HS Math L1 January 2026 Q23; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Two concentric circles form the shaded annulus shown. A chord of the outer circle is 100 m long and is tangent to the inner circle. What is the shaded area?", "choices": [{"key": "A", "text": "\\(100\\pi\\text{ m}^2\\)"}, {"key": "B", "text": "\\(250\\pi\\text{ m}^2\\)"}, {"key": "C", "text": "\\(1000\\pi\\text{ m}^2\\)"}, {"key": "D", "text": "\\(1250\\pi\\text{ m}^2\\)"}, {"key": "E", "text": "\\(2500\\pi\\text{ m}^2\\)"}]}, "explanation": "The radius to the tangent point is perpendicular to the chord and bisects it. If the radii are R and r, the resulting right triangle gives \\(R^2=r^2+50^2\\). Thus the annulus area is \\(\\pi(R^2-r^2)=2500\\pi\\) square meters.", "correct": "E"}, {"id": "92132fbd-b297-9609-9876-5d0acffd190b", "before": {"stem": "Question 23. In the figure above, the area of the shaded part is: (Figure not drawn to scale)", "choices": [{"key": "A", "text": "100𝜋 𝑚2"}, {"key": "B", "text": "250𝜋 𝑚2"}, {"key": "C", "text": "1,000𝜋 𝑚2"}, {"key": "D", "text": "1,250𝜋 𝑚2"}, {"key": "E", "text": "2,500𝜋 𝑚2\n\n 9\nESTII-HS Math L1 January 2026"}], "correct": "E", "explanation": "The 100 m outer-circle chord is tangent to the inner circle at its midpoint. Half the chord is 50 m, so R^2-r^2=50^2. The shaded annulus area is pi(R^2-r^2)=2500pi square meters."}, "source_question_id": "est2_hs_level1_jan_2026-q00023", "source": "ESTII-HS Math L1 January 2026 Q23; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Two concentric circles form the shaded annulus shown. A chord of the outer circle is 100 m long and is tangent to the inner circle. What is the shaded area?", "choices": [{"key": "A", "text": "\\(100\\pi\\text{ m}^2\\)"}, {"key": "B", "text": "\\(250\\pi\\text{ m}^2\\)"}, {"key": "C", "text": "\\(1000\\pi\\text{ m}^2\\)"}, {"key": "D", "text": "\\(1250\\pi\\text{ m}^2\\)"}, {"key": "E", "text": "\\(2500\\pi\\text{ m}^2\\)"}]}, "explanation": "The radius to the tangent point is perpendicular to the chord and bisects it. If the radii are R and r, the resulting right triangle gives \\(R^2=r^2+50^2\\). Thus the annulus area is \\(\\pi(R^2-r^2)=2500\\pi\\) square meters.", "correct": "E"}, {"id": "a35f72ba-7401-6ab9-98fa-2ff0adeca6e8", "before": {"stem": "Question 30. One employee is randomly selected from the company. What is the probability that\n the employee is a man with an annual salary of at least $11,000?", "choices": [{"key": "A", "text": "4\n 25"}, {"key": "B", "text": "32\n 132"}, {"key": "C", "text": "50\n 132"}, {"key": "D", "text": "32\n 55"}, {"key": "E", "text": "35\n 55"}], "correct": "A", "explanation": "The male employees earning at least $11,000 are 20 in [11,13) and 12 in [13,15), or 32 out of 200 employees. Probability 32/200=4/25."}, "source_question_id": "est2_hs_level1_jan_2026-q00290", "source": "ESTII-HS Math L1 January 2026 Q30; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "The table gives annual salaries for all 200 employees in a company. One employee is selected at random. What is the probability that the employee is a man earning at least $11,000 per year?", "choices": [{"key": "A", "text": "4/25"}, {"key": "B", "text": "32/132"}, {"key": "C", "text": "50/132"}, {"key": "D", "text": "32/55"}, {"key": "E", "text": "35/55"}], "assets_patch": {"html": "<table><thead><tr><th>Annual salary ($1,000)</th><th>[5, 7)</th><th>[7, 9)</th><th>[9, 11)</th><th>[11, 13)</th><th>[13, 15)</th></tr></thead><tbody><tr><th>Men</th><td>45</td><td>25</td><td>30</td><td>20</td><td>12</td></tr><tr><th>Women</th><td>15</td><td>20</td><td>10</td><td>15</td><td>8</td></tr></tbody></table>"}}, "explanation": "There are 20 + 12 = 32 men in the salary groups starting at $11,000. The selection is from all 200 employees, so the probability is 32/200 = 4/25.", "correct": "A"}, {"id": "c3716f84-305b-4ecf-9594-481f95c9360f", "before": {"stem": "Question 30. One employee is randomly selected from the company. What is the probability that\n the employee is a man with an annual salary of at least $11,000?", "choices": [{"key": "A", "text": "4\n 25"}, {"key": "B", "text": "32\n 132"}, {"key": "C", "text": "50\n 132"}, {"key": "D", "text": "32\n 55"}, {"key": "E", "text": "35\n 55"}], "correct": "A", "explanation": "The male employees earning at least $11,000 are 20 in [11,13) and 12 in [13,15), or 32 out of 200 employees. Probability 32/200=4/25."}, "source_question_id": "est2_hs_level1_jan_2026-q00030", "source": "ESTII-HS Math L1 January 2026 Q30; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": false, "fields": {"stem": "The table gives annual salaries for all 200 employees in a company. One employee is selected at random. What is the probability that the employee is a man earning at least $11,000 per year?", "choices": [{"key": "A", "text": "4/25"}, {"key": "B", "text": "32/132"}, {"key": "C", "text": "50/132"}, {"key": "D", "text": "32/55"}, {"key": "E", "text": "35/55"}], "assets_patch": {"html": "<table><thead><tr><th>Annual salary ($1,000)</th><th>[5, 7)</th><th>[7, 9)</th><th>[9, 11)</th><th>[11, 13)</th><th>[13, 15)</th></tr></thead><tbody><tr><th>Men</th><td>45</td><td>25</td><td>30</td><td>20</td><td>12</td></tr><tr><th>Women</th><td>15</td><td>20</td><td>10</td><td>15</td><td>8</td></tr></tbody></table>"}}, "explanation": "There are 20 + 12 = 32 men in the salary groups starting at $11,000. The selection is from all 200 employees, so the probability is 32/200 = 4/25.", "correct": "A", "duplicate_of": "a35f72ba-7401-6ab9-98fa-2ff0adeca6e8"}, {"id": "852edbdc-ff69-beb8-d152-a4fe99cb7ece", "before": {"stem": "Question 31. The HR department is organizing a race featuring five employees, each\n representing a different salary class. The probability that the representative of the\n first salary class wins is 𝑝. As the salary class goes up, the probability of winning\n is halved. What is the probability that the employee representing the [5 −7) class\n wins?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "4\n 5"}, {"key": "C", "text": "16\n 31"}, {"key": "D", "text": "1\n 2"}, {"key": "E", "text": "8\n 31\n\n 13\nESTII-HS Math L1 January 2026"}], "correct": "C", "explanation": "The five classes have win probabilities p,p/2,p/4,p/8,p/16, totaling (31/16)p=1. The requested [5,7) class is the first class in the printed salary table, so p=16/31."}, "source_question_id": "est2_hs_level1_jan_2026-q00291", "source": "ESTII-HS Math L1 January 2026 Q31; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "A race has five employees, one from each salary class: [5, 7), [7, 9), [9, 11), [11, 13), and [13, 15) thousand dollars. Exactly one employee wins. The first-class representative wins with probability p, and each successive class has half the preceding probability. What is the probability that the representative of the [5, 7) class wins?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "4/5"}, {"key": "C", "text": "16/31"}, {"key": "D", "text": "1/2"}, {"key": "E", "text": "8/31"}]}, "explanation": "The five mutually exclusive winning probabilities add to 1: \\(p+p/2+p/4+p/8+p/16=31p/16=1\\). The requested class is the first, so its probability is \\(p=16/31\\).", "correct": "C"}, {"id": "c02f7507-92d3-f33e-4ded-994ed325ba84", "before": {"stem": "Question 31. The HR department is organizing a race featuring five employees, each\n representing a different salary class. The probability that the representative of the\n first salary class wins is 𝑝. As the salary class goes up, the probability of winning\n is halved. What is the probability that the employee representing the [5 −7) class\n wins?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "4\n 5"}, {"key": "C", "text": "16\n 31"}, {"key": "D", "text": "1\n 2"}, {"key": "E", "text": "8\n 31\n\n 13\nESTII-HS Math L1 January 2026"}], "correct": "C", "explanation": "The five classes have win probabilities p,p/2,p/4,p/8,p/16, totaling (31/16)p=1. The requested [5,7) class is the first class in the printed salary table, so p=16/31."}, "source_question_id": "est2_hs_level1_jan_2026-q00031", "source": "ESTII-HS Math L1 January 2026 Q31; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": false, "fields": {"stem": "A race has five employees, one from each salary class: [5, 7), [7, 9), [9, 11), [11, 13), and [13, 15) thousand dollars. Exactly one employee wins. The first-class representative wins with probability p, and each successive class has half the preceding probability. What is the probability that the representative of the [5, 7) class wins?", "choices": [{"key": "A", "text": "1"}, {"key": "B", "text": "4/5"}, {"key": "C", "text": "16/31"}, {"key": "D", "text": "1/2"}, {"key": "E", "text": "8/31"}]}, "explanation": "The five mutually exclusive winning probabilities add to 1: \\(p+p/2+p/4+p/8+p/16=31p/16=1\\). The requested class is the first, so its probability is \\(p=16/31\\).", "correct": "C", "duplicate_of": "852edbdc-ff69-beb8-d152-a4fe99cb7ece"}, {"id": "27d369d4-a4d4-cd6f-2eae-843c9978731e", "before": {"stem": "Question 36. Samir has a number of marbles between 300 and 350. When the marbles are\n divided into groups of 12 or groups of 18, there are always 3 marbles left. How\n many marbles does Samir have?", "choices": [{"key": "A", "text": "350"}, {"key": "B", "text": "329"}, {"key": "C", "text": "327"}, {"key": "D", "text": "324"}, {"key": "E", "text": "291\n\n 15\nESTII-HS Math L1 January 2026"}], "correct": "C", "explanation": "N-3 is divisible by lcm(12,18)=36. Between 300 and 350 the only such N is 36*9+3=327."}, "source_question_id": "est2_hs_level1_jan_2026-q00296", "source": "ESTII-HS Math L1 January 2026 Q36; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Samir has between 300 and 350 marbles. Dividing them into groups of 12 or groups of 18 always leaves 3 marbles. How many does he have?", "choices": [{"key": "A", "text": "350"}, {"key": "B", "text": "329"}, {"key": "C", "text": "327"}, {"key": "D", "text": "324"}, {"key": "E", "text": "291"}]}, "explanation": "The number minus 3 must be divisible by both 12 and 18, hence by their least common multiple, 36. The only multiple of 36 between 297 and 347 is 324. Therefore the number of marbles is 324 + 3 = 327. Check: 327 = 12×27 + 3 = 18×18 + 3.", "correct": "C"}, {"id": "5a60cbd7-c94b-425a-a763-16ead3594f09", "before": {"stem": "Question 36. Samir has between 300 and 350 marbles. Dividing them into groups of 12 or groups of 18 always leaves 3 marbles. How many does he have?", "choices": [{"key": "A", "text": "350"}, {"key": "B", "text": "329"}, {"key": "C", "text": "327"}, {"key": "D", "text": "324"}, {"key": "E", "text": "291"}], "correct": "C", "explanation": "N-3 is divisible by lcm(12,18)=36. Between 300 and 350 the only such N is 36*9+3=327."}, "source_question_id": "est2_hs_level1_jan_2026-q00036", "source": "ESTII-HS Math L1 January 2026 Q36; printed page and repeated copy visually checked", "review_note": "Restored mathematical notation and complete context; checked the answer by an independent calculation and checked every printed choice.", "release": true, "fields": {"stem": "Samir has between 300 and 350 marbles. Dividing them into groups of 12 or groups of 18 always leaves 3 marbles. How many does he have?", "choices": [{"key": "A", "text": "350"}, {"key": "B", "text": "329"}, {"key": "C", "text": "327"}, {"key": "D", "text": "324"}, {"key": "E", "text": "291"}]}, "explanation": "The number minus 3 must be divisible by both 12 and 18, hence by their least common multiple, 36. The only multiple of 36 between 297 and 347 is 324. Therefore the number of marbles is 324 + 3 = 327. Check: 327 = 12×27 + 3 = 18×18 + 3.", "correct": "C"}, {"id": "ea35fe21-9bd8-b59c-8848-0cc2d496df1b", "before": {"stem": "Chemistry exam scores for 20 students: 8 9 10 7 9 | 8 12 7 6 16 | 7 6 11 5 13 | 13 8 13 8\nThe number who score 8 or below = x%. What is 2x?", "choices": [{"key": "A", "text": "60"}, {"key": "B", "text": "100"}, {"key": "C", "text": "30"}, {"key": "D", "text": "50"}], "correct": "B", "explanation": "Independently solved and checked against the original source page and printed choices."}, "source_question_id": "stats_probability_revision_may_2026-p2-q1", "source": "Stats & Probability Revision May 2026 page 2; Revision 2 June 2026 page 11; both visually checked", "review_note": "Restored the missing twentieth score, 12, and checked the count directly.", "release": true, "fields": {"stem": "The chemistry scores of 20 students are 8, 9, 10, 7, 9; 8, 12, 7, 6, 16; 7, 6, 11, 5, 13; 13, 8, 13, 8, 12. If x% of the students scored at most 8, what is 2x?"}, "explanation": "There are ten scores at most 8: four 8s, three 7s, two 6s, and one 5. Thus x = (10/20)×100 = 50, so 2x = 100.", "correct": "B"}, {"id": "3273c3c8-0d1c-baa4-34fc-e849e60cefab", "before": {"stem": "Here are some values from a chemistry exam for 20\nstudents. (calc)\n8 9 10 7 9\n8 12 7 6 16\n’; © H&K\nI3 8 13 8 12\nIf the number who get 8 or below represents x%.\nWhat is the value of 2x.", "choices": [{"key": "A", "text": "60"}, {"key": "B", "text": "100"}, {"key": "C", "text": "30"}, {"key": "D", "text": "50"}], "correct": "B", "explanation": "Independently solved and checked against the original scanned page and printed choices."}, "source_question_id": "revision_2_june_2026_a-p11-q8", "source": "Stats & Probability Revision May 2026 page 2; Revision 2 June 2026 page 11; both visually checked", "review_note": "Restored the missing twentieth score, 12, and checked the count directly.", "release": true, "fields": {"stem": "The chemistry scores of 20 students are 8, 9, 10, 7, 9; 8, 12, 7, 6, 16; 7, 6, 11, 5, 13; 13, 8, 13, 8, 12. If x% of the students scored at most 8, what is 2x?"}, "explanation": "There are ten scores at most 8: four 8s, three 7s, two 6s, and one 5. Thus x = (10/20)×100 = 50, so 2x = 100.", "correct": "B"}, {"id": "5f813fc7-c4f2-0370-2f8e-69fb9b511e02", "before": {"stem": "3,20,27.44,60,61\nWhat is the interquartile range for the\nvalues above? (no calc)", "choices": [{"key": "A", "text": "59"}, {"key": "B", "text": "20"}, {"key": "C", "text": "60"}, {"key": "D", "text": "40"}], "correct": "D", "explanation": "Independently solved and checked against the original scanned page and printed choices."}, "source_question_id": "revision_2_june_2026_a-p12-q10", "source": "Revision 2 June 2026, rendered page 12", "review_note": "Restored the comma between 27 and 44; stated the median-of-halves quartile convention explicitly.", "release": true, "fields": {"stem": "Find the interquartile range of 3, 20, 27, 44, 60, 61, using the medians of the lower and upper halves as Q1 and Q3."}, "explanation": "The lower half is 3, 20, 27, whose median is Q1 = 20. The upper half is 44, 60, 61, whose median is Q3 = 60. The interquartile range is Q3 − Q1 = 60 − 20 = 40.", "correct": "D"}, {"id": "8896aba3-a121-8529-4df4-f8d3a7dcee7c", "before": {"stem": "Q72. The graph plotted below represents which of the following functions? Abdelrahman", "choices": [{"key": "A", "text": "f(x) = (x + 1)(x − 2)²"}, {"key": "B", "text": "f(x) = (x − 1)(x + 2)²"}, {"key": "C", "text": "f(x) = (x + 1)(x − 2)"}, {"key": "D", "text": "f(x) = (x − 2)(x + 1)²\n\nAbdelrahman Ghoneem | 01116004434 | EST & SAT Math Page 15"}], "correct": "A", "explanation": "Verified answer key; source and release checks completed."}, "source_question_id": "ghoneem_full_revision_jun_2026-q00071", "source": "Matching original question and graph: Clean bank PAM 008 page 312 / HOA 008 page 7; full revision page 15 Q72", "review_note": "Restored the exact source graph from the matching original question; independently checked its roots and multiplicities.", "release": false, "fields": {"stem": "Which function is represented by the graph?", "choices": [{"key": "A", "text": "\\(f(x)=(x+1)(x-2)^2\\)"}, {"key": "B", "text": "\\(f(x)=(x-1)(x+2)^2\\)"}, {"key": "C", "text": "\\(f(x)=(x+1)(x-2)\\)"}, {"key": "D", "text": "\\(f(x)=(x-2)(x+1)^2\\)"}]}, "explanation": "The graph crosses the x-axis at −1, so (x + 1) is a factor of odd multiplicity. It touches and turns at x = 2, so (x − 2) is squared. It rises to the right and passes through (0, 4), all consistent with (x + 1)(x − 2)².", "correct": "A", "figure_from_id": "2e905225-ae8b-63b0-1de2-dbd31cbbca60", "duplicate_of": "2e905225-ae8b-63b0-1de2-dbd31cbbca60"}]$payload$::jsonb) LOOP
  SELECT * INTO q FROM public.questions WHERE id=(v->>'id')::uuid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=q.id FOR UPDATE;
  IF q.id IS NULL OR k.question_id IS NULL THEN RAISE EXCEPTION 'Missing question/key %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action='question_review_20260928' AND target_id=q.id::text) THEN CONTINUE; END IF;
  IF q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices'
     OR k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation' THEN
    RAISE EXCEPTION 'Concurrent question change %',q.id;
  END IF;
  IF EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE q.id=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
    INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('question_review_deferred_20260928','question',q.id::text,jsonb_build_object('reason','Active exam','proposed',v));
    CONTINUE;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta)
  VALUES('question_review_20260928','question',q.id::text,jsonb_build_object('before_question',to_jsonb(q),'before_key',to_jsonb(k),'verification',v-'before'));
  a=coalesce(q.assets,'{}'::jsonb); patch=coalesce(v->'fields','{}'::jsonb);
  IF v ? 'figure_from_id' THEN
   SELECT assets->'figure' INTO f FROM public.questions WHERE id=(v->>'figure_from_id')::uuid;
   IF f IS NULL THEN RAISE EXCEPTION 'Missing verified figure for %',q.id; END IF;
   a=(a-'figure_required')||jsonb_build_object('figure',f,'figure_verified_source',v->>'figure_from_id');
  END IF;
  a=a||coalesce(patch->'assets_patch','{}'::jsonb)||jsonb_build_object(
    'answer_review','2026-09-28-independent-solution-and-source-check','verification_source',v->>'source',
    'verification_note',v->>'review_note','content_audit','2026-09-28-all-bank-structural-audit');
  IF coalesce((v->>'release')::boolean,false) THEN
   a=(a-'release_hold_reason')||jsonb_build_object('verified_release','2026-09-28-independent-solution-and-source-check');
  ELSIF v ? 'duplicate_of' THEN
   a=a||jsonb_build_object('release_hold_reason','Duplicate of reviewed question','duplicate_of',v->>'duplicate_of');
  END IF;
  UPDATE public.questions SET stem=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
   topic=coalesce(patch->>'topic',q.topic),type=coalesce(patch->>'type',q.type),assets=a WHERE id=q.id;
  UPDATE public.question_keys SET correct=coalesce(v->'correct',k.correct),explanation=coalesce(v->>'explanation',k.explanation) WHERE question_id=q.id;
  IF v->>'source_question_id' IS NOT NULL THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta)
   SELECT 'staged_question_review_20260928','question_bank',b.question_id,jsonb_build_object('before',to_jsonb(b)) FROM public.question_bank b WHERE b.question_id=v->>'source_question_id';
   UPDATE public.question_bank SET stem_text=coalesce(patch->>'stem',q.stem),choices=coalesce(patch->'choices',q.choices),
    answer_key=coalesce(v->'correct',k.correct)#>>'{}',answer_explanation=coalesce(v->>'explanation',k.explanation),
    answer_key_status='independently_verified',needs_review=false,review_reasons=jsonb_build_array(v->>'review_note')
   WHERE question_id=v->>'source_question_id' AND coalesce((v->>'release')::boolean,false);
  END IF;
 END LOOP;
END;
$review$;
SELECT jsonb_build_object('applied',(SELECT count(*) FROM public.audit_log WHERE action='question_review_20260928'),
 'deferred',(SELECT count(*) FROM public.audit_log WHERE action='question_review_deferred_20260928')) AS result;
